function bestOutcome(event,key){var rows=[];(event.bookmakers||[]).forEach(function(b){var m=(b.markets||[]).find(function(x){return x.key===key});if(m)(m.outcomes||[]).forEach(function(o){rows.push({book:b.title,book_key:b.key,name:o.name,price:o.price,point:o.point,last_update:m.last_update})})});return rows}
