function currentBoardRows(){var q=($('#gameSearch')?.value||'').toLowerCase().trim(),view=$('#boardView')?.value||'all',sort=$('#boardSort')?.value||'time',fav=loadFav();var a=EVENTS.filter(function(e){var match=(e.away_team+' '+e.home_team).toLowerCase();return (!q||match.indexOf(q)>=0)&&(view!=='favorites'||fav.has(e.id))});if(sort==='fav')a.sort(function(x,y){return Number(fav.has(y.id))-Number(fav.has(x.id))||new Date(x.commence_time)-new Date(y.commence_time)});else if(sort==='alpha')a.sort(function(x,y){return (x.away_team+' '+x.home_team).localeCompare(y.away_team+' '+y.home_team)});else a.sort(function(x,y){return new Date(x.commence_time)-new Date(y.commence_time)});return a}
