function decisionQuality(p){if(p&&Number.isFinite(Number(p.decision_quality)))return Math.round(p.decision_quality);if(!p)return 0;var pr=p.projection||{};var score=.18*Number(pr.data_quality||0)+.15*Number(p.market_coverage||pr.coverage_score||0)+.14*Number(p.market_effective_agreement||pr.effective_agreement||0)+.19*Number(p.market_support_strength||0)+.10*Math.max(0,100-Number(pr.uncertainty||50));score+=Math.min(15,Math.max(0,Number(p.adjusted_edge||0)*250));score+=Math.min(9,Math.max(0,Number(p.estimated_ev||0)*160));if(p.hard_rock)score+=4;if(p.market_inside_fair_range)score-=5;if(Number(p.independent_disagreement||0)>=.12)score-=8;return Math.max(0,Math.min(100,Math.round(score)))}
