function signalHtml(m){var v=Math.max(-.65,Math.min(.65,Number(m.value)||0)),w=Math.abs(v)/.65*50,cls=v>=0?'pos':'neg',side=v>0?'HOME':v<0?'AWAY':'NEUTRAL';return '<div class="signal"><div><b>'+esc(m.name)+'</b><div class="small subtle">'+side+' • '+Math.round(m.confidence||0)+'/100</div></div><div class="sigbar"><i class="'+cls+'" style="width:'+w+'%"></i></div><div class="sigscore">'+(v>0?'+':'')+v.toFixed(2)+'</div></div>'}
