async function lockOfficialCard(){if(!LAST)return;var picks=(LAST.plays||[]).filter(function(p){return ['CORE','SECONDARY'].includes(p.tier)});if(!picks.length){alert('There are no Core or Secondary plays to lock.');return}try{var d=await api('/api/card/lock',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({keys:picks.map(serverStableKey)})});await refreshServerData();renderAudit();alert('Official card locked on the server ✓ ('+(d.locked||0)+' new lock'+((d.locked||0)===1?'':'s')+')')}catch(e){alert('Lock error: '+e.message)}}
async function runScan(){try{var stale=!BOARD_SYNCED_AT||(Date.now()-BOARD_SYNCED_AT)>120000;if(!EVENTS.length||stale){setProgress(true,'Refreshing board first…',15,stale?'Odds snapshot older than 2 minutes':'No cached board on this device');var sport=$('#sport').value,markets=$('#markets').value;var od=await api('/api/odds?sport='+encodeURIComponent(sport)+'&markets='+encodeURIComponent(markets)+(stale?'&force=1':''));EVENTS=od.events||[];QUOTA=od.quota||null;BOARD_SYNCED_AT=od.fetched_at?new Date(od.fetched_at).getTime():Date.now();if(!EVENTS.length)throw new Error('No upcoming pregame events found.')}setProgress(true,'Building blind projections…',38,'Sport-specific data + independent thesis');setTimeout(function(){setProgress(true,'Challenging the market…',67,'De-vig consensus + uncertainty + support')},500);var d=await api('/api/scan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({events:EVENTS,sport:$('#sport').value,markets:$('#markets').value,board_synced_at:BOARD_SYNCED_AT?new Date(BOARD_SYNCED_AT).toISOString():null})});LAST=d;saveSnapshots(d);setProgress(true,'Running final release gates…',91,'Freshness + EV + cushion + confirmation + sanity firewall');await refreshServerData();setTimeout(function(){setProgress(false)},250);populateLabSelect();renderCard();renderBoard();renderAudit();renderAutopilot();nav('card')}catch(e){setProgress(false);alert('Scan error: '+e.message)}}
async function gradeAudit(auto){try{if(!auto&&$('#gradeResults'))$('#gradeResults').disabled=true;var d=await api('/api/results/grade',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});await refreshServerData();renderAudit();if(!auto&&!(d.graded||0))alert('No finished games were ready to grade yet.')}catch(e){if(!auto)alert('Grade error: '+e.message)}finally{if($('#gradeResults'))$('#gradeResults').disabled=false}}
function autoGrade(){refreshServerData().then(function(){renderAudit()}).catch(function(){})}
